use std::fs

fn prec(c: char) -> int {
    if c == '^' { return 3 }
    if c == '*' || c == '/' { return 2 }
    if c == '+' || c == '-' { return 1 }
    0
}

fn convert(line: string) -> string {
    let cs: Vec<char> = line.chars().collect()
    let n: int = cs.len() as int
    let mut out: Vec<string> = []
    let mut stack: Vec<char> = []
    let mut expect = true
    let mut i: int = 0
    while i < n {
        let c = cs[i as usize]
        if c == ' ' || c == '\t' || c == '\r' {
            i += 1
        } else if c >= '0' && c <= '9' {
            if !expect { return "error" }
            let mut num = ""
            while i < n && cs[i as usize] >= '0' && cs[i as usize] <= '9' {
                num = num + cs[i as usize].to_string()
                i += 1
            }
            out.push(num)
            expect = false
        } else if c == '(' {
            if !expect { return "error" }
            stack.push(c)
            i += 1
        } else if c == ')' {
            if expect { return "error" }
            let mut found = false
            while stack.len() > 0 {
                let t = stack.pop().unwrap_or(' ')
                if t == '(' {
                    found = true
                    break
                }
                out.push(t.to_string())
            }
            if !found { return "error" }
            i += 1
        } else if prec(c) > 0 {
            if expect { return "error" }
            while stack.len() > 0 {
                let t = stack[stack.len() - 1]
                if t == '(' { break }
                if prec(t) > prec(c) || (prec(t) == prec(c) && c != '^') {
                    out.push(t.to_string())
                    stack.pop()
                } else {
                    break
                }
            }
            stack.push(c)
            expect = true
            i += 1
        } else {
            return "error"
        }
    }
    if expect { return "error" }
    while stack.len() > 0 {
        let t = stack.pop().unwrap_or(' ')
        if t == '(' { return "error" }
        out.push(t.to_string())
    }
    out.join(" ")
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim().len() == 0 { continue }
        println(convert(line))
    }
}

